def matches_intent(message: str, intent: str) -> bool:
    if not message:
        return False
    lower = message.lower()
    keywords = INTENT_KEYWORDS.get(intent, [])
    return any(keyword in lower for keyword in keywords)


def normalize_language(code: str | None) -> str:
    if not code:
        return ""
    key = code.strip().lower()
    return LANGUAGE_ALIASES.get(key, key)


def get_message(key: str, language: str, **kwargs: Any) -> str:
    lang = normalize_language(language) or "hi"
    lang_values = STRINGS.get(lang, {})
    value = lang_values.get(key)
    fallback = STRINGS.get("hi", {}).get(key)
    if fallback is None:
        fallback = STRINGS.get("en", {}).get(key, "")
    missing = value is None or value == ""
    if missing:
        value = fallback
    if isinstance(value, list):
        value = random.choice(value)
    text = str(value).format(**kwargs) if kwargs else str(value)
    if (missing or key not in lang_values) and lang not in {"hi", "en"}:
        try:
            from .translator import translate_text

            return translate_text(text, lang)
        except Exception:
            return text
    return text


def _char_script(ch: str) -> str | None:
    code = ord(ch)
    for script, ranges in SCRIPT_RANGES.items():
        for start, end in ranges:
            if start <= code <= end:
                return script
    return None


def _has_latin_letters(text: str) -> bool:
    return any(("a" <= ch <= "z") or ("A" <= ch <= "Z") for ch in text)


def _is_neutral_short(text: str) -> bool:
    cleaned = " ".join(text.split())
    if not cleaned:
        return True
    if len(cleaned) <= 3:
        return True
    return cleaned in NEUTRAL_SHORT_TOKENS


def detect_language(text: str, current_language: str, default_language: str) -> str:
    if not text:
        return current_language or default_language

    raw = text.strip()
    lower = raw.lower()

    if lower.startswith("/lang"):
        parts = lower.split()
        if len(parts) > 1:
            normalized = normalize_language(parts[1])
            if normalized in LANGUAGE_NAMES:
                return normalized

    for code, hints in LANGUAGE_HINTS.items():
        if any(hint in lower for hint in hints):
            return code

    script_counts: dict[str, int] = {}
    for ch in raw:
        script = _char_script(ch)
        if not script:
            continue
        script_counts[script] = script_counts.get(script, 0) + 1

    if script_counts:
        script = max(script_counts.items(), key=lambda item: item[1])[0]
        if script == "bengali":
            if any(hint in lower for hint in LANGUAGE_HINTS.get("as", [])):
                return "as"
            return "bn"
        if script == "arabic":
            if any(hint in lower for hint in LANGUAGE_HINTS.get("sd", [])):
                return "sd"
            if any(hint in lower for hint in LANGUAGE_HINTS.get("ks", [])):
                return "ks"
            return "ur"
        if script == "devanagari":
            for dev_code in ["mr", "ne", "sa", "kok", "mai", "brx", "doi", "hi"]:
                if any(hint in lower for hint in LANGUAGE_HINTS.get(dev_code, [])):
                    return dev_code
            return "hi"
        return SCRIPT_DEFAULT.get(script, current_language or default_language)

    if _is_neutral_short(lower):
        return current_language or default_language
    if _has_latin_letters(raw):
        return "en"

    return current_language or default_language


def detect_faq_type(message: str) -> tuple[str | None, str | None]:
    if not message:
        return None, None
    lower = message.lower()
    for key, patterns_by_lang in FAQ_PATTERNS.items():
        for lang, patterns in patterns_by_lang.items():
            if any(pattern in lower for pattern in patterns):
                return key, lang
    return None, None
